oxy_webhelp_navlinks = {"arch_network_connectivity_requirements-d39307e8081":{"topics":[{"title":"Archival network throttling","shortdesc":"<p class=\"shortdesc\">Archival network throttling limits the bandwidth that a Rubrik cluster uses to         archive data, leaving more bandwidth available for backup and recovery operations. You can         set a global threshold and configure time-based overrides to increase or decrease the limit         for specific periods.<\/p>","href":"archival\/arch_nw_throttling.html","attributes":{"data-id":"arch_nw_throttling"},"menu":{"hasChildren":false},"tocID":"arch_nw_throttling-d39307e8092","topics":[]},{"title":"Configuring archival network throttling and scheduling overrides","shortdesc":"<p class=\"shortdesc\">To free up bandwidth for backup and restore operations on your Rubrik cluster by         limiting the bandwidth used by the archiving jobs on the cluster, configure archival network         throttling for the Rubrik cluster. You can also configure the system to override archival         network throttling threshold during scheduled periods.<\/p>","href":"archival\/arch_configuring_nw_throttling.html","attributes":{"data-id":"arch_configuring_nw_throttling"},"menu":{"hasChildren":false},"tocID":"arch_configuring_nw_throttling-d39307e8103","topics":[]},{"title":"Archival proxy settings","shortdesc":"<p class=\"shortdesc\">The archival location configuration includes an option for setting proxy server         properties to route archival data and requests through the proxy server.<\/p>","href":"archival\/arch_proxy_settings.html","attributes":{"data-id":"arch_proxy_settings"},"menu":{"hasChildren":false},"tocID":"arch_proxy_settings-d39307e8114","topics":[]},{"title":"Compute proxy settings","shortdesc":"<p class=\"shortdesc\">The archival location configuration includes an option for setting proxy server         properties to route the API calls for instantiating virtual machines on the archival         location through the proxy server.<\/p>","href":"archival\/arch_compute_proxy_settings.html","attributes":{"data-id":"arch_compute_proxy_settings"},"menu":{"hasChildren":false},"tocID":"arch_compute_proxy_settings-d39307e8125","topics":[]}]}};